import { execFileSync } from "node:child_process";

// Shared by the local:setup and local:preview scripts. Local D1 and R2 data
// live under the state directory, which `pnpm dev` reads as well.
export const WRANGLER_CONFIG = "wrangler.jsonc";
// Generated by `pnpm build`: wrangler.jsonc plus the built Worker and assets.
export const BUILT_WRANGLER_CONFIG = "dist/server/wrangler.json";
export const LOCAL_STATE_DIR = ".wrangler/state";
export const LOCAL_ADMIN_EMAIL = "admin@localhost";
export const RECIPES_DATABASE = "cookmark-recipes";

// Runs wrangler quietly and surfaces its output only when it fails.
export const runWrangler = (args: ReadonlyArray<string>): void => {
  try {
    execFileSync("wrangler", args, { stdio: ["ignore", "pipe", "pipe"] });
  } catch (error) {
    const { stdout, stderr } = error as { stdout?: Buffer; stderr?: Buffer };
    console.error(stdout?.toString(), stderr?.toString());
    throw new Error(`wrangler ${args.slice(0, 3).join(" ")} failed`);
  }
};
